import{_ as t,o as a,c as i,ak as o}from"./chunks/framework.Da_1AWg-.js";const r="/projects/GPS-Module/en/latest/assets/image3.CmrCMQTw.webp",n="/projects/GPS-Module/en/latest/assets/image4.DYOc6f4a.webp",s="/projects/GPS-Module/en/latest/assets/image5.BO6sPQEA.webp",l="/projects/GPS-Module/en/latest/assets/image6.BZLUfV9A.webp",c="/projects/GPS-Module/en/latest/assets/image8.DRAQSw1Y.webp",b=JSON.parse('{"title":"1. User Manual","description":"","frontmatter":{},"headers":[],"relativePath":"docs/1.User_Manual.md","filePath":"docs/1.User_Manual.md"}'),p={name:"docs/1.User_Manual.md"};function d(h,e,u,m,g,f){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="_1-user-manual" tabindex="-1">1. User Manual <a class="header-anchor" href="#_1-user-manual" aria-label="Permalink to &quot;1. User Manual&quot;">​</a></h1><h2 id="_1-1-gps-module-introduction" tabindex="-1">1.1 GPS Module Introduction <a class="header-anchor" href="#_1-1-gps-module-introduction" aria-label="Permalink to &quot;1.1 GPS Module Introduction&quot;">​</a></h2><p>The GPS module is a high-performance BDS/GNSS positioning and navigation module based on <code>ATGM336H-5N</code>. This module supports a variety of satellite navigation systems, including all of China&#39;s Beidou-2 and Beidou-3 satellites, the United States&#39; GPS, Russia&#39;s GLONASS, and Japan&#39;s QZSS. It is capable of simultaneously receiving satellite signals from these navigation systems, enabling joint positioning, navigation, and guidance. Additionally, the module offers advantages such as high sensitivity, low power consumption, and low cost, making it suitable for various applications including vehicle navigation, handheld positioning, and wearable devices.</p><h3 id="_1-1-1-module-feature" tabindex="-1">1.1.1 Module Feature <a class="header-anchor" href="#_1-1-1-module-feature" aria-label="Permalink to &quot;1.1.1 Module Feature&quot;">​</a></h3><p>(1) Supports all Beidou-2 and Beidou-3 satellites (Satellites 1~63)</p><p>(2) Supports single system positioning of BDS/GPS/QZSS satellite navigation system, as well as any combination of multi-system joint positioning</p><p>(3) Supports A-GNSS</p><p>(4) Cold start capture sensitivity: -148dBm</p><p>(5) Tracking sensitivity: -162dBm</p><p>(6) Positioning accuracy: 2.5 meters (CEP50)</p><p>(7) First positioning time: 32 seconds</p><p>(8) Low power consumption: continuous operation at 25mA@3.3V</p><p>(9) Built-in antenna detection and antenna short circuit protection function</p><h3 id="_1-1-2-interface-diagram" tabindex="-1">1.1.2 Interface Diagram <a class="header-anchor" href="#_1-1-2-interface-diagram" aria-label="Permalink to &quot;1.1.2 Interface Diagram&quot;">​</a></h3><img loading="lazy" height="452" width="600" src="'+r+'" class="common_img"><h3 id="_1-1-3-communication-protocol" tabindex="-1">1.1.3 Communication Protocol <a class="header-anchor" href="#_1-1-3-communication-protocol" aria-label="Permalink to &quot;1.1.3 Communication Protocol&quot;">​</a></h3><p>To access the details about the communication protocol, please refer to the PDF file saved in <a href="./Appendix.html">Protocol Specification for CASIC Multi-Mode Satellite Navigation Receivers</a>.</p><h2 id="_1-2-pc-software-use-instructions" tabindex="-1">1.2 PC Software Use Instructions <a class="header-anchor" href="#_1-2-pc-software-use-instructions" aria-label="Permalink to &quot;1.2 PC Software Use Instructions&quot;">​</a></h2><h3 id="_1-2-1-open-the-software" tabindex="-1">1.2.1 Open the Software <a class="header-anchor" href="#_1-2-1-open-the-software" aria-label="Permalink to &quot;1.2.1 Open the Software&quot;">​</a></h3><p>Extract the <a href="./Appendix.html">GnssToolKit3.zip</a> to the local disk.</p><p>Navigate to the folder <a href="./Appendix.html">Appendix</a> and, double-click <a href="./Appendix.html">GnssToolKit3.exe</a> <img loading="lazy" height="30" width="159" src="'+n+'"> to open the software. Upon entering the interface, begin by selecting three icons: one for displaying the satellite position view, another for the basic view, and the third for the carrier-to-noise ratio view. This setup will facilitate real-time monitoring of satellites, star data, and corresponding effects.</p><img loading="lazy" height="807" width="1250" src="'+s+'" class="common_img"><h3 id="_1-2-2-connect-to-receiver" tabindex="-1">1.2.2 Connect to Receiver <a class="header-anchor" href="#_1-2-2-connect-to-receiver" aria-label="Permalink to &quot;1.2.2 Connect to Receiver&quot;">​</a></h3><p>To power on the receiver, connect the computer&#39;s serial port to the receiver&#39;s serial port using a serial port cable. If you are using a USB to serial port cable and encounter random data transmission issues, please follow these steps: disconnect the receiver&#39;s power, open the USB serial port using appropriate software, then power on the receiver. When converting from USB to a serial port chip, be aware that garbled characters in serial port communication may occur, potentially causing system startup errors.</p><h3 id="_1-2-3-serial-port-setting" tabindex="-1">1.2.3 Serial Port Setting <a class="header-anchor" href="#_1-2-3-serial-port-setting" aria-label="Permalink to &quot;1.2.3 Serial Port Setting&quot;">​</a></h3><p>Click-on the <strong>&quot;Serial Port&quot;</strong> option to configure the serial port.</p><img loading="lazy" height="196" width="498" src="'+l+'" class="common_img"><ul><li><strong>Serial Port Configuration</strong></li></ul><p>When configuring the serial port name, selecting <strong>&quot;Serial port name&quot;</strong> will display all serial ports available in the system. If the serial port number font appears gray (e.g., <code>COM7</code>), it indicates that the serial port device is busy and cannot be accessed by the program, possibly due to occupation by other processes. To establish a connection between the software and the receiver, simply click on the serial port number corresponding to the receiver.</p><p>(1) Baud Rate Configuration</p><p>To configure the baud rate, select the <strong>&quot;Baud rate&quot;</strong> menu item to view the valid baud rates for the receiver. The default baud rate is 9600. Users should select the appropriate baud rate according to the receiver&#39;s specifications. It is crucial for the software to function properly with the receiver.</p><p>(2) Communication</p><p>If unsure about the receiver&#39;s baud rate, users can open the NMEA view in the View menu and try each baud rate individually. If a readable navigation message appears in the NMEA view, it indicates that the current baud rate selection is consistent with the receiver&#39;s baud rate.</p><img loading="lazy" height="178" width="420" src="'+c+'" class="common_img"><p>(3) Serial Port Status</p><p>The software&#39;s bottom status bar includes an indicator light for the serial port status. An illuminated icon indicates that the serial port is open, while a grayed-out icon indicates that the serial port is closed. If the serial port indicator light flashes, it indicates active data communication through the serial port.</p>',36)])])}const S=t(p,[["render",d]]);export{b as __pageData,S as default};
